import io

# ── FIX 1: honest range detection ────────────────────────────────────────────
p='overrides/app/pages/product-detail/variantScopedPrice.ts'
s=io.open(p,encoding='utf-8').read()

s=s.replace("""export type ScopedVariant = {
  productId?: string;
  variationValues?: Record<string, string | undefined>;
  [key: string]: unknown;
};""",
"""export type ScopedVariant = {
  productId?: string;
  variationValues?: Record<string, string | undefined>;
  /** Selling price. Read by `collapseIfUniform` — the same field `getPriceData` reads. */
  price?: number;
  /** Per-pricebook tiers; the highest is presumptively the list price, per `getPriceData`. */
  tieredPrices?: { price?: number }[];
  [key: string]: unknown;
};

/**
 * `getPriceData` derives `isRange` structurally — `(isMaster && variants.length > 1) || isASet`
 * (product-utils.js:165). It never compares prices, so a colourway whose sizes all share one
 * sale price and one RRP is still flagged a range. `selectPdpProductInfo` suppresses Was/Now
 * whenever `isRange` is set, so on any multi-size garment PRC-09's pair never rendered.
 *
 * Collapsing a uniformly-priced set to one variant makes the flag honest: a single variant
 * cannot be a range, so `currentPrice`/`listPrice`/`isOnSale` resolve to the definite pair the
 * design asks for. A genuinely mixed set is returned untouched and stays flagged, which is what
 * keeps "Was $795 Now $595" off a colourway where only one size is marked down.
 */
const listPriceOf = (v: ScopedVariant): number | undefined =>
  v.tieredPrices?.length
    ? Math.max(...v.tieredPrices.map((t) => t.price ?? Number.NEGATIVE_INFINITY))
    : undefined;

const collapseIfUniform = (variants: ScopedVariant[]): ScopedVariant[] => {
  if (variants.length < 2) return variants;
  const sameSale = new Set(variants.map((v) => v.price)).size === 1;
  const sameList = new Set(variants.map(listPriceOf)).size === 1;
  return sameSale && sameList ? [variants[0]] : variants;
};""",1)

s=s.replace("""  } else {
    return null; // no selection yet
  }""",
"""  } else {
    // No selection yet. Price across every variant rather than bailing to the caller's
    // master-level `priceData` — that fallback is the same computation minus the
    // uniformity collapse, so bailing here is exactly what hid Was/Now on a bare PDP URL.
    matchingVariants = masterVariants;
  }""",1)

s=s.replace("""  if (!matchingVariants.length) return null;
  return getPriceData({ ...masterProduct, variants: matchingVariants });""",
"""  if (!matchingVariants.length) return null;
  return getPriceData({ ...masterProduct, variants: collapseIfUniform(matchingVariants) });""",1)
