"""export type ScopedVariant = {
  productId?: string;
  variationValues?: Record<string, string | undefined>;
  /** Selling price — the same field `getPriceData`'s `findLowestPrice` reads. */
  price?: number;
  /** Per-pricebook tiers; the highest is presumptively the list price, per `getPriceData`. */
  tieredPrices?: { price?: number }[];
  [key: string]: unknown;
};

/**
 * True when every variant in the set carries the same selling price AND the same list price —
 * i.e. the set is a single definite price, not a range.
 *
 * `getPriceData` derives `isRange` structurally: `(isMaster && variants.length > 1) || isASet`
 * (product-utils.js:165). It never compares prices, so a colourway whose sizes all share one
 * sale price and one RRP is still flagged a range. `selectPdpProductInfo` suppresses Was/Now
 * whenever `isRange` is set (PRC-09), so on a multi-size garment — Zimmermann's usual shape —
 * the pair never rendered. `currentPrice` and `listPrice` were already correct; only the flag
 * was wrong, so only the flag is corrected below.
 */
const pricesAreUniform = (variants: ScopedVariant[]): boolean => {
  if (variants.length < 2) return true;
  const listOf = (v: ScopedVariant) =>
    v.tieredPrices?.length ? Math.max(...v.tieredPrices.map((t) => t.price ?? -Infinity)) : undefined;
  return new Set(variants.map((v) => v.price)).size === 1 && new Set(variants.map(listOf)).size === 1;
};""",1)

s=s.replace("""  } else {
    return null; // no selection yet
  }""",
"""  } else {
    // No selection yet. Scope to every variant rather than returning `null` — that fallback
    // handed the caller a master-level `priceData` carrying the same structurally-wrong
    // `isRange`, which is what hid Was/Now on a bare PDP URL.
    matchingVariants = masterVariants;
  }""",1)

s=s.replace("""  if (!matchingVariants.length) return null;
  return getPriceData({ ...masterProduct, variants: matchingVariants });""",
"""  if (!matchingVariants.length) return null;
  const priceData = getPriceData({ ...masterProduct, variants: matchingVariants });
  // Narrow `isRange` only — never widen it. A set SFCC did not flag stays unflagged.
  return priceData?.isRange && pricesAreUniform(matchingVariants)
    ? { ...priceData, isRange: false }
    : priceData;""",1)
