/**
 * Guards PRC-09 / AC1 against SFCC's structural `isRange`.
 *
 * Deliberately uses the REAL `getPriceData` — `variantScopedPrice.test.ts` mocks it, so it can
 * only assert which arguments were passed and is blind to what price actually comes out. This
 * file is the counterpart: it computes real prices from real pricebook-shaped fixtures.
 */
import { describe, test, expect } from 'vitest';
import { selectVariantScopedPriceData } from './variantScopedPrice';
import { selectPdpProductInfo, type PdpSourcePrice } from './productInfo';

const size = (s: string, colour: string, sale: number, list: number) => ({
  productId: `M-${colour}-${s}`,
  variationValues: { color: colour, size: s },
  price: sale,
  tieredPrices: [{ price: sale, quantity: 1 }, { price: list, quantity: 1 }],
});
const master = (variants: ReturnType<typeof size>[]) => ({
  id: 'M', name: 'INDRA PLUNGE HALTER MAXI DRESS', type: { master: true }, variants,
});
const fmt = (a: number) => `$${a.toLocaleString('en-AU', { minimumFractionDigits: 2 })}`;
const info = (product: unknown, pd: unknown) =>
  selectPdpProductInfo(product as never, pd as PdpSourcePrice, 'AUD', fmt);

describe('isRange uniformity — PRC-09 / AC1', () => {
  const uniform = ['0', '2', '4', '6', '8', '10'].map((s) => size(s, 'X', 595, 795));

  test('bare PDP URL, uniform markdown across all sizes → definite Was/Now', () => {
    const pd = selectVariantScopedPriceData(master(uniform), null, undefined, undefined);
    expect(pd.isRange).toBe(false);
    expect(info(master(uniform), pd)!.wasPrice).toBe('$795.00');
    expect(info(master(uniform), pd)!.price).toBe('$595.00');
  });

  test('colour-only, uniform markdown → definite Was/Now', () => {
    const pd = selectVariantScopedPriceData(master(uniform), null, undefined, 'X');
    expect(pd.isRange).toBe(false);
    expect(info(master(uniform), pd)!.wasPrice).toBe('$795.00');
  });

  test('broken size run — only one size marked down → Was/Now suppressed', () => {
    const mixed = [size('0', 'X', 795, 795), size('2', 'X', 795, 795), size('6', 'X', 595, 795)];
    const pd = selectVariantScopedPriceData(master(mixed), null, undefined, 'X');
    expect(pd.isRange).toBe(true);
    expect(info(master(mixed), pd)!.wasPrice).toBeUndefined();
  });

  test('no sale at all → single price, no Was/Now', () => {
    const full = ['0', '2'].map((s) => size(s, 'X', 795, 795));
    const pd = selectVariantScopedPriceData(master(full), null, undefined, 'X');
    expect(pd.isOnSale).toBe(false);
    expect(info(master(full), pd)!.wasPrice).toBeUndefined();
  });
});
